import{c as r,Q as t,j as a,m as c}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"課程講義","description":"","frontmatter":{},"headers":[],"relativePath":"lectures/index.md","filePath":"lectures/index.md","lastUpdated":1785912489000}'),s={name:"lectures/index.md"};function o(l,e,n,u,i,d){return t(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="課程講義" tabindex="-1">課程講義 <a class="header-anchor" href="#課程講義" aria-label="Permalink to &quot;課程講義&quot;">​</a></h1><p>本課程涵蓋 Claude Code 與 Agent Harness 的核心概念，從基礎原理到組織治理，共十二堂。</p><p>內容以 Anthropic 官方文件與 <a href="/cc-workspace-docs/research/claude-blog/">claude.com/blog 歸檔</a>（153 個條目，2025-11 ~ 2026-07）為一手來源，每堂課末列出對應的官方原文連結。</p><h2 id="part-1-基礎-lecture-01–03" tabindex="-1">Part 1：基礎（Lecture 01–03） <a class="header-anchor" href="#part-1-基礎-lecture-01–03" aria-label="Permalink to &quot;Part 1：基礎（Lecture 01–03）&quot;">​</a></h2><h3 id="lecture-01-claude-code-與-harness-基礎" tabindex="-1"><a href="/cc-workspace-docs/lectures/lecture-01-foundations/">Lecture 01：Claude Code 與 Harness 基礎</a> <a class="header-anchor" href="#lecture-01-claude-code-與-harness-基礎" aria-label="Permalink to &quot;[Lecture 01：Claude Code 與 Harness 基礎](/lectures/lecture-01-foundations/)&quot;">​</a></h3><p>Agent = Model + Body + Harness 三層等式、Agentic Loop 三階段、Agent 失敗五層級歸因診斷、導入成效的量化錨點。</p><p><strong>關鍵概念</strong>：Harness first、先修 Harness 再換模型、刪鷹架與強化閘門同時發生</p><hr><h3 id="lecture-02-claude-md-與規則設計" tabindex="-1"><a href="/cc-workspace-docs/lectures/lecture-02-claude-md/">Lecture 02：CLAUDE.md 與規則設計</a> <a class="header-anchor" href="#lecture-02-claude-md-與規則設計" aria-label="Permalink to &quot;[Lecture 02：CLAUDE.md 與規則設計](/lectures/lecture-02-claude-md/)&quot;">​</a></h3><p>CLAUDE.md 四層作用域、Ratchet 原則、觸發點判斷表（何時該加 CLAUDE.md / Skill / MCP / Hook / Plugin）、Context Assembly 四層。</p><p><strong>關鍵概念</strong>：請求 ≠ 保證、規則不是零成本、每 3–6 個月審閱</p><hr><h3 id="lecture-03-context-engineering" tabindex="-1"><a href="/cc-workspace-docs/lectures/lecture-03-context-engineering/">Lecture 03：Context Engineering</a> <a class="header-anchor" href="#lecture-03-context-engineering" aria-label="Permalink to &quot;[Lecture 03：Context Engineering](/lectures/lecture-03-context-engineering/)&quot;">​</a></h3><p>Context Rot 量化數據、Sub-agent 作為 Context Firewall、Claude 5 世代六條新規則、Prompt Caching 的五個禁令。</p><p><strong>關鍵概念</strong>：system prompt −80% 無退化、可刪的是鷹架不是閘門、cache hit rate 是健康指標</p><hr><h2 id="part-2-架構-lecture-04–06" tabindex="-1">Part 2：架構（Lecture 04–06） <a class="header-anchor" href="#part-2-架構-lecture-04–06" aria-label="Permalink to &quot;Part 2：架構（Lecture 04–06）&quot;">​</a></h2><h3 id="lecture-04-harness-三層架構" tabindex="-1"><a href="/cc-workspace-docs/lectures/lecture-04-harness-architecture/">Lecture 04：Harness 三層架構</a> <a class="header-anchor" href="#lecture-04-harness-三層架構" aria-label="Permalink to &quot;[Lecture 04：Harness 三層架構](/lectures/lecture-04-harness-architecture/)&quot;">​</a></h3><p>Planner / Generator / Evaluator 三層分離、25 種 Hooks 事件、Exit Code 規約、Harness 複雜度隨模型能力調整。</p><p><strong>關鍵概念</strong>：Generator 不能自評、獨立 verifier 讓 false positive 減半</p><hr><h3 id="lecture-05-memory-與-workspace-管理" tabindex="-1"><a href="/cc-workspace-docs/lectures/lecture-05-memory-workspace/">Lecture 05：Memory 與 Workspace 管理</a> <a class="header-anchor" href="#lecture-05-memory-與-workspace-管理" aria-label="Permalink to &quot;[Lecture 05：Memory 與 Workspace 管理](/lectures/lecture-05-memory-workspace/)&quot;">​</a></h3><p>跨 session 三層狀態架構、Git Worktrees、Sub-agent 委派與工具作用域、Model 分層與 Advisor 模式。</p><p><strong>關鍵概念</strong>：In-context vs External memory、<code>/fork</code> 語義已改、不要 mid-session 換模型</p><hr><h3 id="lecture-06-安全沙箱與-proxy" tabindex="-1"><a href="/cc-workspace-docs/lectures/lecture-06-security/">Lecture 06：安全沙箱與 Proxy</a> <a class="header-anchor" href="#lecture-06-安全沙箱與-proxy" aria-label="Permalink to &quot;[Lecture 06：安全沙箱與 Proxy](/lectures/lecture-06-security/)&quot;">​</a></h3><p>Native Sandboxing、Filesystem + Network 雙重隔離、細粒度 Permission、CISO 四個評估問題、六類 agentic 漏洞。</p><p><strong>關鍵概念</strong>：環境層優先於模型層、外部輸入是資料不是指令、憑證在網路邊界才替換</p><hr><h2 id="part-3-擴展-lecture-07–09" tabindex="-1">Part 3：擴展（Lecture 07–09） <a class="header-anchor" href="#part-3-擴展-lecture-07–09" aria-label="Permalink to &quot;Part 3：擴展（Lecture 07–09）&quot;">​</a></h2><h3 id="lecture-07-skills-設計與-progressive-disclosure" tabindex="-1"><a href="/cc-workspace-docs/lectures/lecture-07-skills/">Lecture 07：Skills 設計與 Progressive Disclosure</a> <a class="header-anchor" href="#lecture-07-skills-設計與-progressive-disclosure" aria-label="Permalink to &quot;[Lecture 07：Skills 設計與 Progressive Disclosure](/lectures/lecture-07-skills/)&quot;">​</a></h3><p>七種行為調整機制的選擇、九大 Skill 類別、自由度校準、Progressive Disclosure、Claude A/B 迭代法。</p><p><strong>關鍵概念</strong>：Description 是選擇引擎、窄橋 vs 開闊平原、準確率 21% → 95%</p><hr><h3 id="lecture-08-sub-agents、agent-teams-與-dynamic-workflows" tabindex="-1"><a href="/cc-workspace-docs/lectures/lecture-08-subagents-workflows/">Lecture 08：Sub-agents、Agent Teams 與 Dynamic Workflows</a> <a class="header-anchor" href="#lecture-08-sub-agents、agent-teams-與-dynamic-workflows" aria-label="Permalink to &quot;[Lecture 08：Sub-agents、Agent Teams 與 Dynamic Workflows](/lectures/lecture-08-subagents-workflows/)&quot;">​</a></h3><p>三個協作層級、委派的硬門檻、五種協調模式、六種 workflow 模式、W28–W31 扇出治理變更。</p><p><strong>關鍵概念</strong>：工具呼叫 &gt; 20 次必須委派、預設不再巢狀 spawn、背景 session 會自動 commit/push</p><hr><h3 id="lecture-09-模型選型與-effort-經濟學" tabindex="-1"><a href="/cc-workspace-docs/lectures/lecture-09-model-selection/">Lecture 09：模型選型與 Effort 經濟學</a> <a class="header-anchor" href="#lecture-09-模型選型與-effort-經濟學" aria-label="Permalink to &quot;[Lecture 09：模型選型與 Effort 經濟學](/lectures/lecture-09-model-selection/)&quot;">​</a></h3><p>四個 class 定位、現役模型規格與定價、effort 等級、Advisor 策略、自建 eval。</p><p><strong>關鍵概念</strong>：class × effort 二維框架、每 token 價格 ≠ 每任務價格、Advisor 90% 效能 / 63% 成本</p><hr><h2 id="part-4-工程化-lecture-10–12" tabindex="-1">Part 4：工程化（Lecture 10–12） <a class="header-anchor" href="#part-4-工程化-lecture-10–12" aria-label="Permalink to &quot;Part 4：工程化（Lecture 10–12）&quot;">​</a></h2><h3 id="lecture-10-驗證迴圈與-code-review" tabindex="-1"><a href="/cc-workspace-docs/lectures/lecture-10-verification/">Lecture 10：驗證迴圈與 Code Review</a> <a class="header-anchor" href="#lecture-10-驗證迴圈與-code-review" aria-label="Permalink to &quot;[Lecture 10：驗證迴圈與 Code Review](/lectures/lecture-10-verification/)&quot;">​</a></h3><p>驗證迴圈四種部署形態、Oracle 先驗、裝完成的六種捷徑、Code Review 與 REVIEW.md。</p><p><strong>關鍵概念</strong>：觸發權在 harness 不在模型、獨立 verifier false positive −50%、測試檔被改即紅旗</p><hr><h3 id="lecture-11-mcp-整合與外部系統" tabindex="-1"><a href="/cc-workspace-docs/lectures/lecture-11-mcp/">Lecture 11：MCP 整合與外部系統</a> <a class="header-anchor" href="#lecture-11-mcp-整合與外部系統" aria-label="Permalink to &quot;[Lecture 11：MCP 整合與外部系統](/lectures/lecture-11-mcp/)&quot;">​</a></h3><p>三種 transport 與 scope、intent-grouped 工具設計、Tool Search、OAuth 與 managed MCP、MCP 2026-07-28 規格。</p><p><strong>關鍵概念</strong>：Tool Search 降 85%+ token、3–6 個 server 上限、stateless core</p><hr><h3 id="lecture-12-plugins、自動化與組織治理" tabindex="-1"><a href="/cc-workspace-docs/lectures/lecture-12-governance/">Lecture 12：Plugins、自動化與組織治理</a> <a class="header-anchor" href="#lecture-12-plugins、自動化與組織治理" aria-label="Permalink to &quot;[Lecture 12：Plugins、自動化與組織治理](/lectures/lecture-12-governance/)&quot;">​</a></h3><p>Plugin 打包、Routines 三種觸發器、Vaults、大型 codebase 三層 context 架構、AI 原生工程組織三指標。</p><p><strong>關鍵概念</strong>：Agentic Search 不是 RAG、每 3–6 個月審閱、風險可見且有界</p><hr><h2 id="學習路徑" tabindex="-1">學習路徑 <a class="header-anchor" href="#學習路徑" aria-label="Permalink to &quot;學習路徑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路徑</th><th>內容</th><th>預估時間</th></tr></thead><tbody><tr><td><strong>入門</strong></td><td>Lecture 01 → 02 → 03 → <a href="/cc-workspace-docs/projects/project-01-init-workspace/">Project 01</a></td><td>4 小時</td></tr><tr><td><strong>架構</strong></td><td>Lecture 04 → 05 → 06 → <a href="/cc-workspace-docs/projects/project-02-harness-design/">Project 02</a></td><td>5 小時</td></tr><tr><td><strong>擴展</strong></td><td>Lecture 07 → 08 → 09</td><td>4 小時</td></tr><tr><td><strong>工程化</strong></td><td>Lecture 10 → 11 → 12</td><td>4 小時</td></tr></tbody></table><p><strong>按角色的建議切入點</strong>：</p><ul><li><strong>個人開發者</strong>：01 → 02 → 03 → 07 → 10（先讓單人工作流可靠）</li><li><strong>技術主管 / 平台團隊</strong>：01 → 04 → 09 → 12（先看架構與成本治理）</li><li><strong>SRE / 安全</strong>：01 → 06 → 10 → 12（先看邊界與稽核）</li></ul><h2 id="延伸資源" tabindex="-1">延伸資源 <a class="header-anchor" href="#延伸資源" aria-label="Permalink to &quot;延伸資源&quot;">​</a></h2><ul><li><a href="/cc-workspace-docs/projects/">實作專案</a> — 兩個動手練習</li><li><a href="/cc-workspace-docs/resources/">資源庫</a> — 最佳實踐與研究摘要精選</li><li><a href="/cc-workspace-docs/research/">研究資料庫</a> — 論文、深度報告、官方 blog 歸檔全文</li></ul>',61)])])}const g=r(s,[["render",o]]);export{p as __pageData,g as default};
